'use strict';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,published,jiraScope={issues:[]},aiReport={sections:[],attention:[]},docControls={pairs:[],pdFeatures:[],validationFeatures:[],tests:{parent:null,children:[]}},state={mode:'focus',category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0,view:'dashboard',dueField:'due',asOf:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul'}).format(new Date())};
fetch('jira-history.json').then(r=>r.json()).then(v=>{jiraScope=v; if(data) render();}).catch(()=>{});
fetch('ai-report.json').then(r=>r.json()).then(v=>{aiReport=v; if(data) render();}).catch(()=>{});
fetch('doc-controls.json').then(r=>r.json()).then(v=>{docControls=v; if(data) render();}).catch(()=>{});
const colors={G:'#409776',R:'#d59e36',D:'#c74f64','P-D':'#638ac7',Done:'#0b7f79',Unknown:'#c6ceda'};
const fmt=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)?new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):d||'—';
const badge=r=>`<span class="badge ${esc(r.status)}">${esc(r.jiraStatus||Plan.labels[r.status]||r.status)}</span>`;
const base=()=>{const source=state.mode==='docs'?(data.docRows||[]):data.rows;return source.filter(Analytics.scopes[state.mode].match);};
function selected(){return base().filter(r=>(!state.category||r.section===state.category)&&(!state.team||(r.team||'Not recorded')===state.team)&&(!state.status||r.status===state.status)&&(!state.section||r.section===state.section)&&(!state.owner||(r.owner||'Not recorded')===state.owner)&&(!state.group||(r.group||'Not recorded')===state.group)&&(!state.dueMonth||r[state.dueField].startsWith(state.dueMonth))&&(!state.attention||(Analytics.isDate(r[state.dueField])&&r[state.dueField]<state.asOf&&!Analytics.milestoneDone(r,state.dueField)))&&(!state.query||[r.title,r.group,r.section,r.owner,r.team,r.ticket,r.summary,r.sdk].join(' ').toLowerCase().includes(state.query.toLowerCase())));}
function scopedJiraTickets(){const issues=state.mode==='all'?(jiraScope.issues||[]):jiraIssuesForMode(state.mode);return issues.filter(i=>(!state.category||i.section===state.category)&&(!state.section||i.section===state.section)&&(!state.query||[i.key,i.title,i.section,i.assignee,i.currentStatus].join(' ').toLowerCase().includes(state.query.toLowerCase())));}
function controls(){const rows=base();$('team').innerHTML='<option value="">All teams</option>'+[...new Set(rows.map(r=>r.team||'Not recorded'))].sort().map(t=>`<option>${esc(t)}</option>`).join('');$('status').innerHTML='<option value="">All statuses</option>'+Object.entries(Plan.labels).map(([v,t])=>`<option value="${v}">${t}</option>`).join('');$('section').innerHTML='<option value="">All sections</option>'+[...new Set(rows.map(r=>r.section))].map(t=>`<option>${esc(t)}</option>`).join('');for(const f of ['team','status','section'])$(f).value=state[f];$('search').value=state.query;$('section-label').hidden=state.mode!=='all';}
function render(){
 const rows=selected(),total=base().length;state.page=Math.min(state.page,Math.max(0,Math.ceil(rows.length/25)-1));
 $('page-title').textContent=Analytics.scopes[state.mode].title;
 document.querySelectorAll('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.mode===state.mode);b.setAttribute('aria-current',b.dataset.mode===state.mode?'page':'false')});
 $('category-cards').hidden=state.mode!=='focus'||state.view==='dashboard';$('category-cards').innerHTML=Plan.focus.map(s=>{const tickets=(jiraScope.issues||[]).filter(i=>i.section===s),code=i=>{const x=String(i.currentStatus||'').toLowerCase();return x.includes('pre-silicon')||x==='p-d'?'P-D':x==='done'||x==='closed'?'Done':x?'G':'Unknown'};return `<button class="category ${state.category===s?'active':''}" data-category="${esc(s)}" aria-pressed="${state.category===s}"><span class="cat-top">${s}</span><span class="cat-count">${tickets.length}</span><small>Jira tickets</small><div class="mini-bar" aria-hidden="true">${Object.entries(colors).map(([k,c])=>`<span style="flex:${tickets.filter(i=>code(i)===k).length};background:${c}"></span>`).join('')}</div></button>`}).join('');
  const tickets=jiraScope.issues||[],norm=s=>String(s||'').toLowerCase(),jiraDone=r=>['done','closed'].includes(norm(r.currentStatus)),pdDone=r=>['pre-silicon done','p-d','done','closed'].includes(norm(r.currentStatus)),dueAttention=state.view==='dates'?tickets.filter(r=>r.pdDueDate&&r.pdDueDate<state.asOf&&!pdDone(r)).length:tickets.filter(r=>r.dueDate&&r.dueDate<state.asOf&&!jiraDone(r)).length,metrics=[['Jira tickets',tickets.length,'Filter 19455',''],['Done',tickets.filter(r=>jiraDone(r)).length,'Current Jira status',''],['Pre-silicon done',tickets.filter(r=>norm(r.currentStatus).includes('pre-silicon')||norm(r.currentStatus)==='p-d').length,'Current Jira status',''],['In progress',tickets.filter(r=>norm(r.currentStatus).includes('progress')).length,'Current Jira status',''],[state.view==='dates'?'P-Due attention':'Due-date attention',dueAttention,state.view==='dates'?'Past P-Due date':'Past Jira due date','danger']]; $('metrics').innerHTML=metrics.map(([label,n,sub,cls])=>`<div class="metric ${cls}"><span class="caption">${label}</span><strong>${n}</strong><small>${sub}</small></div>`).join('');
 $('list-title').textContent=({history:'Weekly evolution',dates:'Delivery dates',risks:'Early warnings',dependencies:'Dependency review',report:'Management report'})[state.view]|| (state.view==='dashboard'?'Program dashboard':state.mode==='docs'?'Development specifications':state.mode==='all'?'Ticket register':Analytics.scopes[state.mode].title);const allTicketView=['dashboard','history','dates','risks','dependencies','report'].includes(state.view),ticketCount=allTicketView?(jiraScope.issues?.length||0):scopedJiraTickets().length;$('count').textContent=`${ticketCount} Jira ticket${ticketCount===1?'':'s'} · ${allTicketView?'filter 19455':'selected scope'} · master-plan workbook is supporting context`;
 const page=rows.slice(state.page*25,(state.page+1)*25);
 $('results').innerHTML=state.view==='dashboard'?(state.mode==='docs'?renderDocControls()+renderDashboard(rows):state.mode==='validation'?renderValidationTests()+renderDashboard(rows):renderDashboard(rows)):['history','dates','risks','dependencies','report'].includes(state.view)?renderIntelligence(['dates','risks','report'].includes(state.view)?jiraRows(rows):rows):rows.length?(state.view==='schedule'?renderSchedule(page):renderRegister(page)):'<div class="empty">No supporting master-plan entries match these filters.</div>';
 if(state.view==='dashboard'&&jiraScope.issues?.length){document.querySelectorAll('.cohort').forEach((el,i)=>{if(!el.querySelector('.status-cumulative'))el.insertAdjacentHTML('beforeend',jiraStatusSummary(['sdk','host','ai','ref'][i]));});}
 $('schedule-view').hidden=false;for(const v of ['dashboard','register','schedule','history','dates','risks','dependencies','report'])$(v+'-view').setAttribute('aria-pressed',state.view===v);
 document.querySelector('.table-footer').hidden=!['register','schedule'].includes(state.view); document.querySelector('.filters').hidden=state.view==='history'; $('category-cards').hidden=state.view!=='register'||state.mode!=='focus';
 $('chart-filter-label').textContent=[state.section&&'Section: '+state.section,state.owner&&'Assignee: '+state.owner,state.group&&'Group: '+state.group,state.dueMonth&&(state.dueField==='preDue'?'Pre-silicon':'Feature')+' due month: '+state.dueMonth,state.attention&&'Past due date; completion unconfirmed as of '+state.asOf].filter(Boolean).join(' · ');
 if(state.view==='schedule'){const month=new Date().toLocaleString('en-US',{month:'short'}),year=new Date().getFullYear(),index=data.weeks.findIndex(w=>w.month===month&&w.year===year),scroller=$('results').querySelector('.table-scroll');if(scroller&&index>=0)scroller.scrollLeft=index*55;}
 $('page-label').textContent=rows.length?`Supporting entries ${state.page*25+1}–${Math.min((state.page+1)*25,rows.length)} of ${rows.length}`:'0 supporting entries';$('prev').disabled=!state.page;$('next').disabled=(state.page+1)*25>=rows.length;
}
function renderSchedule(rows){
 const months=[];for(const w of data.weeks){const label=w.month+' '+w.year;if(months.at(-1)?.label===label)months.at(-1).span++;else months.push({label,span:1})}
 return `<p class="schedule-legend">Original weekly cells and colors · Click a feature for full annotations and due dates. Colored cells do not by themselves indicate completion.</p><div class="table-scroll"><table class="weekly"><thead><tr><th class="frozen" rowspan="2">Feature / deliverable</th>${months.map(m=>`<th colspan="${m.span}">${m.label}</th>`).join('')}</tr><tr>${data.weeks.map(w=>`<th>${w.week}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td class="frozen feature"><button data-row="${r.row}">${esc(r.title)}</button><span class="subline">${esc(r.key||r.team)} · ${esc(Plan.labels[r.status]||r.status)}</span></td>${data.weeks.map(w=>{const t=r.timeline.find(t=>t.column===w.column);return `<td class="week-cell" title="${esc(w.year+' '+w.week+(t?.text?' · '+t.text:''))}">${t?`<span style="${t.color?'background:#'+t.color+';color:'+contrast(t.color):''}">${esc(t.text)}${!t.text?'<span class="sr-only">Colored schedule cell</span>':''}</span>`:''}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function contrast(hex){const nums=hex.match(/../g).map(x=>parseInt(x,16));return nums[0]*.299+nums[1]*.587+nums[2]*.114>145?'#172638':'#ffffff'}
function renderRegister(rows){return `<p class="schedule-legend">Jira tickets are authoritative. The entries below are supporting representations from the master-plan workbook.</p><div class="table-scroll"><table><thead><tr><th>Feature / deliverable</th><th>Owner</th><th>Status</th><th>Pre-silicon due</th><th>Feature Done target</th><th>Jira ticket</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="feature"><button data-row="${r.row}">${esc(r.title)}</button><span class="subline">${esc(r.section)} / ${esc(r.group)} · supporting source ${r.row}${r.sdk?' · '+esc(r.sdk):''}</span></td><td>${esc(r.owner)||'Unassigned'}<span class="subline">${esc(r.team)||'Team not recorded'}</span></td><td>${badge(r)}</td><td class="nowrap">${esc(fmt(r.preDue))}</td><td class="nowrap">${esc(fmt(r.due))}</td><td class="nowrap">${r.url?`<a target="_blank" rel="noopener noreferrer" href="${esc(r.url)}">${esc(r.key||r.ticket)} ↗</a>`:esc(r.ticket)||'—'}</td></tr>`).join('')}</tbody></table></div>`;}
function renderValidationTests(){const features=docControls.validationFeatures||[],children=docControls.tests?.children||[],covered=features.filter(f=>f.tests?.length),link=k=>k?`<a href="https://bos-semi.atlassian.net/browse/${esc(k)}" target="_blank" rel="noopener noreferrer">${esc(k)} ↗</a>`:'',testChip=t=>`<span class="validation-test-chip"><span>${link(t.key)}</span><b>${esc(t.summary||'Test request')}</b><small>${esc(t.status||'Unknown')}${t.assignee?' · '+esc(t.assignee):' · Unassigned'}</small></span>`;return `<div class="validation-board"><div class="section-intro"><div><span class="eyebrow">VALIDATION TRACEABILITY</span><h3>Feature test requests from ITCP-47</h3><p>Feature labels come from the supporting Spec. worksheet. Test requests, status and assignee come directly from the Jira child tickets of <a href="https://bos-semi.atlassian.net/browse/ITCP-47" target="_blank" rel="noopener noreferrer">ITCP-47 ↗</a>.</p></div><div class="signal-grid"><div><strong>${features.length}</strong><span>features reviewed</span></div><div><strong>${covered.length}</strong><span>with matched test requests</span></div><div class="danger"><strong>${features.length-covered.length}</strong><span>without a matched child request</span></div><div><strong>${children.length}</strong><span>ITCP-47 child requests</span></div></div></div>${covered.length?`<div class="success-callout"><b>Quantization trace is present</b><p>The Quantization feature is linked to both ITCP-48 (LLM) and ITCP-50 (Vision QDQ), with current Jira status shown below.</p></div>`:''}<p class="evidence-note">Matching is a wording-based review aid. An unmatched feature means no current child summary was confidently matched; it does not prove that testing is absent. This dashboard never creates Jira links.</p><div class="table-scroll"><table><thead><tr><th>Feature</th><th>Workbook context</th><th>Test request(s) found under ITCP-47</th></tr></thead><tbody>${features.map(f=>`<tr class="${f.tests?.length?'':'coverage-gap'}"><th>${esc(f.feature)}${f.sourceKey?`<span class="subline">${esc(f.sourceKey)} · supporting feature label</span>`:''}</th><td>${esc(f.group)||'—'}</td><td>${f.tests?.length?f.tests.map(testChip).join(''):'<span class="coverage-empty">No confidently matched child test request</span>'}</td></tr>`).join('')||'<tr><td colspan="3">No Spec. feature labels were captured in the supporting workbook.</td></tr>'}</tbody></table></div><h3>Current ITCP-47 child requests</h3><div class="validation-child-grid">${children.map(t=>`<a class="validation-child-card" href="https://bos-semi.atlassian.net/browse/${esc(t.key)}" target="_blank" rel="noopener noreferrer"><strong>${esc(t.key)}</strong><span>${esc(t.summary||'Test request')}</span><small>${esc(t.status||'Unknown')}${t.assignee?' · '+esc(t.assignee):' · Unassigned'}</small></a>`).join('')||'<p>No child requests were retrieved from ITCP-47.</p>'}</div></div>`;}
function renderDocControls(){const pairs=(docControls.pairs||[]),actions=pairs.filter(p=>p.reviewControl?.action),link=k=>k?`<a href="https://bos-semi.atlassian.net/browse/${esc(k)}" target="_blank" rel="noopener noreferrer">${esc(k)} ↗</a>`:'Not recorded';return `<div class="doc-control-board"><div class="section-intro"><div><span class="eyebrow">DOCUMENTATION CONTROL</span><h3>SRS, SAD and SUD writing → review</h3><p>Direct Jira reads for the documentation worksheet. The workbook supplies the writing/review pairing; Jira supplies current status and assignee.</p></div><div class="signal-grid"><div><strong>${pairs.length}</strong><span>writing/review pairs</span></div><div class="danger"><strong>${actions.length}</strong><span>review actions required</span></div><div><strong>${docControls.pdFeatures?.length||0}</strong><span>P-D feature tickets with tests</span></div></div></div>${actions.length?`<div class="warning-callout"><b>Review action required</b><p>${actions.length} writing ticket${actions.length===1?'':'s'} is Jira P-D while its paired review is not both In Progress and assigned. Update Jira before calling the document reviewed.</p></div>`:'<div class="success-callout"><b>No P-D review exceptions detected</b><p>Every directly observed P-D writing ticket has an assigned review in progress, or no P-D writing ticket is currently recorded.</p></div>'}<div class="table-scroll"><table><thead><tr><th>Document</th><th>Writing ticket</th><th>Writing status</th><th>Review ticket</th><th>Review status</th><th>Reviewer</th><th>Control</th></tr></thead><tbody>${pairs.map(p=>`<tr class="${p.reviewControl?.action?'risk-row':''}"><th>${esc(p.writing.title)}<span class="subline">${esc(p.writing.jira?.summary||p.writing.group||'')}</span></th><td>${link(p.writing.key)}</td><td>${esc(p.writing.jira?.status||'Not retrieved')}</td><td>${link(p.review?.key)}</td><td>${esc(p.review?.jira?.status||'Not retrieved')}</td><td>${esc(p.review?.jira?.assignee||'Unassigned')}</td><td>${p.reviewControl?.required?(p.reviewControl.action?'Action required':'Ready'):'Monitor until writing is P-D'}</td></tr>`).join('')}</tbody></table></div><h3>Test traceability from ITCP-47</h3><p class="evidence-note">The test request epic is <a href="https://bos-semi.atlassian.net/browse/ITCP-47" target="_blank" rel="noopener noreferrer">ITCP-47 ↗</a>. Matching is a review aid based on ticket wording; it does not create Jira links.</p><div class="table-scroll"><table><thead><tr><th>P-D feature ticket</th><th>Feature</th><th>Retrieved test request(s)</th></tr></thead><tbody>${(docControls.pdFeatures||[]).map(p=>`<tr><td>${link(p.key)}</td><td>${esc(p.title)}<span class="subline">${esc(p.section)}</span></td><td>${p.tests.map(t=>`${link(t.key)} <span class="subline">${esc(t.summary||t.error||'Not retrieved')} · ${esc(t.status||'Unknown')}</span>`).join('<br>')}</td></tr>`).join('')||'<tr><td colspan="3">No current Jira-filter feature is P-D in the captured evidence.</td></tr>'}</tbody></table></div></div>`;}
function showDetail(row){const r=(state.mode==='docs'?(data.docRows||[]):data.rows).find(r=>r.row===row);if(!r)return;$('detail-eyebrow').textContent=`${r.section} · Supporting master-plan source ${r.sheet||data.sheet} row ${r.row}`;$('detail-body').innerHTML=`<h2>${esc(r.title)}</h2>${badge(r)}<p>${esc(r.group)}</p><dl class="detail-grid">${[['Team',r.team],['Assignee',r.owner],['P-D target',fmt(r.preDue)],['Feature Done target',fmt(r.due)],['Jira ticket',r.key||'Not recorded']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)||'Not recorded'}</dd></div>`).join('')}</dl><h3>Current progress summary</h3><div class="note">${esc(r.summary)||'No progress summary recorded.'}</div><h3>Source links</h3>${r.links.length?r.links.map(l=>`<p><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.text)} ↗</a> <small>Column ${l.column}</small></p>`).join(''):r.url?`<p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.key)} ↗</a></p>`:'<p>No link recorded in the worksheet.</p>'}<h3>Weekly plan annotations</h3>${r.timeline.length?`<ul class="timeline-items">${r.timeline.map(t=>`<li><time>${t.year} ${t.week} · ${t.month}</time><span>${t.color?`<i class="color-swatch" style="background:#${t.color}"></i>`:''}${esc(t.text)||'Color-only marker'}</span></li>`).join('')}</ul>`:'<p>No annotations or colored cells in the weekly schedule.</p>'}`;$('detail').showModal();}
function showDocDetail(row){const previous=state.mode;state.mode='docs';showDetail(row);state.mode=previous;}
function sourceInfo(){$('detail-eyebrow').textContent='DATA SOURCE';$('detail-body').innerHTML='<h2>About this dashboard</h2><p><b>Authoritative scope:</b> Jira filter 19455 (<code>labels = "host_sw_master_plan" ORDER BY created DESC</code>). Ticket status, assignee, due date, creation date and changelog are captured directly from Jira when a refresh is requested in Codex.</p><p><b>Supporting context:</b> '+esc(data.name)+'<br>Development worksheet: '+esc(data.sheet)+'<br>Documentation worksheet: '+esc(data.documentationSheet||'Not recorded')+'. Workbook entries map Level 1 areas and pair SRS/SAD/SUD writing with reviews; they do not increase the Jira ticket count.</p><p>The dashboard does not poll Jira. Each requested Codex refresh stores a new dated artifact, rebuilds Jira history, regenerates the management summary and republishes the private site. Missing weeks are not estimated.</p><p>Jira due dates and workbook P-D / Feature Done dates are targets. They do not prove actual completion. Done is the only final Jira completion state used here; pre-silicon done remains a separate milestone.</p><p>For documentation controls, the dashboard reads document Jira keys directly because some document tickets are outside filter 19455. ITCP-47 is the test-request epic; matching test requests are evidence links, not automatically created Jira links.</p><p>Dependency suggestions are unconfirmed hypotheses requiring owner review. This dashboard never creates Jira links. Blank owners, dates and statuses remain visible as missing evidence.</p>';$('detail').showModal();}
function updateSource(){$('sheet-name').textContent='Supporting workbook: '+data.sheet;$('source').textContent='Jira filter 19455 · '+(data.mode==='saved'?'saved supporting context':data.mode==='session'?'unsaved supporting context':'published supporting context')+' · Workbook saved '+new Date(data.modifiedAt).toLocaleString('en-GB',{timeZone:'Asia/Seoul',dateStyle:'medium',timeStyle:'short'})+' KST · Jira refresh on request';$('footer-source').textContent='Jira filter 19455 · supporting workbook: '+data.name;$('reset').hidden=data===published;}
document.addEventListener('click',e=>{const cat=e.target.closest('[data-category]'),r=e.target.closest('[data-row]'),dr=e.target.closest('[data-doc-row]'),nav=e.target.closest('[data-mode]');if(cat){state.category=state.category===cat.dataset.category?'':cat.dataset.category;state.page=0;render()}if(dr)showDocDetail(Number(dr.dataset.docRow));else if(r)showDetail(Number(r.dataset.row));if(nav){Object.assign(state,{mode:nav.dataset.mode,category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();render()}});
for(const f of ['team','status','section'])$(f).addEventListener('change',e=>{state[f]=e.target.value;state.page=0;render()});$('search').addEventListener('input',e=>{state.query=e.target.value;state.page=0;render()});$('clear').onclick=()=>{Object.assign(state,{category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();render()};$('prev').onclick=()=>{state.page--;render()};$('next').onclick=()=>{state.page++;render()};$('close-detail').onclick=()=>$('detail').close();$('source-info').onclick=sourceInfo;
$('import').onclick=()=>$('file').click();
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('The durable snapshot limit is 1 MB per workbook.');const bytes=new Uint8Array(await file.arrayBuffer());const next=Plan.parseWorkbook(XLSX.read(bytes,{type:'array',cellDates:true,cellStyles:true}),{name:file.name,modifiedAt:new Date(file.lastModified).toISOString(),mode:'session'});let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));next.workbookBase64=btoa(binary);next.observedAt=new Date().toISOString();data=next;historyState.viewedId='';Object.assign(state,{category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();updateSource();render();$('message').textContent='Loaded supporting master-plan context. Saving workbook…';try{await saveCurrent();}catch(error){$('message').textContent='Supporting workbook loaded but NOT saved: '+error.message+' Keep this page open and retry from Weekly evolution.';}}catch(err){$('message').textContent='Could not load supporting workbook: '+err.message;}finally{e.target.value='';}};
$('reset').onclick=()=>{data=published;historyState.viewedId="";Object.assign(state,{category:'',query:'',team:'',status:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();updateSource();render();$('message').textContent='Restored the published workbook snapshot.'};
for(const view of ['dashboard','register','schedule','history','dates','risks','dependencies','report'])$(view+'-view').onclick=()=>{state.view=view;render()};
if(document.modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'filter_master_plan',title:'Filter the master plan',description:'Change the visible plan view and search text. Returns matching Jira ticket context and supporting master-plan entries; does not change source data.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['focus','req','docs','validation','all']},query:{type:'string',maxLength:200},status:{type:'string',enum:['','G','R','D','P-D','Done','Unknown']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!data)throw new Error('The workbook is still loading.');if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['mode','query','status'].includes(k))||!['focus','req','docs','validation','all'].includes(input.mode)||('query'in input&&(typeof input.query!=='string'||input.query.length>200))||('status'in input&&!['','G','R','D','P-D','Done','Unknown'].includes(input.status)))throw new Error('Invalid plan filters.');Object.assign(state,{mode:input.mode,query:input.query||'',status:input.status||'',team:'',category:'',section:'',owner:'',group:'',dueMonth:'',attention:'',page:0});controls();render();const rows=selected();return {count:rows.length,rows:rows.slice(0,25).map(r=>({row:r.row,title:r.title,key:r.key,status:r.status,due:r.due}))};}},{signal:life.signal})).catch(()=>{});}catch{}}
fetch('source.json').then(r=>{if(!r.ok)throw new Error('Source could not be loaded');return r.json()}).then(d=>{data=published=d;controls();updateSource();render();initIntelligence()}).catch(e=>{$('message').textContent=e.message+'. Reload this page to try again.'});
